/* Biểu tượng UMC (phần hình vuông của logo Bệnh viện Đại học Y Dược TP.HCM), nhúng sẵn dạng data URL
 * để vẽ được lên canvas khi mở trang bằng file:// (ảnh file riêng có thể không nạp kịp hoặc bị chặn).
 * Tạo từ public/brand/logo-ngang.png của portal hội nghị; ảnh gốc: assets/umc-bieu-tuong.png. */
(function (root) {
  "use strict";
  function taoAnh(src) { var img = new Image(); img.decoding = "async"; img.src = src; return img; }
  var NHO = "data:image/png;base64,";
  var LON = "data:image/png;base64,";
  root.UMC = {
    nho: taoAnh(NHO), lon: taoAnh(LON), srcLon: LON,
    /** true khi ảnh đã sẵn sàng để vẽ lên canvas. */
    san: function (img) { return img.complete && img.naturalWidth > 0; },
  };
})(window);
